def find_method(lib, keyword_name):
    """Finds method in library based on keyword name."""
    attrs = dir(lib)
    normalized_attrs = [each.lower() for each in attrs]
    keyword_name = keyword_name.replace(' ', '_').lower()
    if keyword_name in normalized_attrs:
        return attrs[normalized_attrs.index(keyword_name)]
